import type {ThemeName} from './types';

/**
 * Категориальные слоты 1–2 (синий, оранжевый). Порядок фиксирован, цвет
 * привязан к индексу серии. Проверено validate_palette.js: CVD ΔE ≥ 8, контраст ≥ 3:1
