import type {ChartData} from '@gravity-ui/charts';
import type {YagrWidgetData} from '@gravity-ui/chartkit/yagr';

import {getSeriesColor} from './palette';
import type {ThemeName, TimeSeriesData} from './types';

// Здесь только типы движков (import type стирается при сборке), поэтому модуль
// не тянет код графических библиотек в основной бандл.

const SECOND_AXIS_ERROR = 'Все серии делят одну ось Y: двойные оси не поддерживаются';

function assertAligned(data: TimeSeriesData) {
  for (const s of data.series) {
    if (s.values.length !== data.timeline.length) {
      throw new Error(`Серия «${s.name}»: ${s.values.length} значений на ${data.timeline.length} меток времени`);
    }
  }
}

const formatter = (unit?: string) => (value: number) =>
  `${new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 1}).format(value)}${unit ? ` ${unit}` : ''}`;

/** Обычный линейный график (gravity-charts): умеренное число точек, маркеры, легенда. */
export function toGravityChartsData(data: TimeSeriesData, theme: ThemeName): ChartData {
  assertAligned(data);
  const fmt = formatter(data.unit);
  return {
    series: {
      data: data.series.map((s, i) => ({
        type: 'line' as const,
        id: s.id,
        name: s.name,
        color: getSeriesColor(theme, i),
        lineWidth: 2,
        data: data.timeline.flatMap((x, idx) => {
          const y = s.values[idx];
          return y === null ? [] : [{x, y}];
        }),
        tooltip: {valueFormat: undefined},
      })),
    },
    xAxis: {type: 'datetime'},
    yAxis: [{labels: {numberFormat: {format: 'number'}}, title: {text: data.unit}}],
    legend: {enabled: data.series.length > 1},
    tooltip: {
      valueFormat: undefined,
      // оставляем дефолтный тултип движка; единицы показываем в подписи оси
    },
  } as ChartData;
}

/** Плотный временной ряд (Yagr/uPlot): тысячи точек, без маркеров, canvas. */
export function toYagrData(data: TimeSeriesData, theme: ThemeName): YagrWidgetData {
  assertAligned(data);
  const fmt = formatter(data.unit);
  return {
    data: {
      timeline: data.timeline,
      graphs: data.series.map((s, i) => ({
        id: s.id,
        name: s.name,
        data: s.values,
        color: getSeriesColor(theme, i),
        type: 'line' as const,
        width: 1.5,
        spanGaps: false,
      })),
    },
    libraryConfig: {
      chart: {
        size: undefined,
        series: {type: 'line', spanGaps: false},
      },
      axes: {
        y: {
          // подпись оси с единицами
          values: (_u: unknown, ticks: number[]) => ticks.map((t) => fmt(t)),
        },
      },
      legend: {show: data.series.length > 1},
      cursor: {
        // маркеры только под курсором — на плотном ряду постоянные маркеры = шум
        markers: {size: 8},
      },
      tooltip: {show: true, tracking: 'sticky'},
      scales: {y: {type: 'linear', range: 'nice'}},
    },
  } as unknown as YagrWidgetData;
}

export {SECOND_AXIS_ERROR};
